import 'jest';
import { decodeChatMessage, encodeChatMessage } from '../../src';

describe('Chat', () => {

    describe('encodeChatMessage()', () => {
        it('will correctly replace emojis with hexcode strings &#000000-FFFFFF', () => {
            expect(encodeChatMessage('😮‍💨', true))
                .toBe(`&amp;#01f62e&amp;#00200d&amp;#01f4a8`);
        });

        it('will correctly replace emojis with base10 strings &#0-99999999;', () => {
            expect(encodeChatMessage('😮‍💨', true, true))
                .toBe(`&amp;#128558;&amp;#8205;&amp;#128168;`);
        });

        it('will correctly replace emojis with nothing if emoji support is false', () => {
            expect(encodeChatMessage('😮‍💨', false))
                .toBe(``);
        });


        it('will replace certain symbols with html encoded ones', () => {
            expect(encodeChatMessage(`<tag> 'single' & "quote" </tag>`, false))
                .toBe(`&lt;tag&gt; &#39;single&#39; &amp; &quot;quote&quot; &lt;/tag&gt;`);
        });
    });

    describe('decodeChatMessage()', () => {
        it('will correctly replace encoded emojis with the emoji', () => {
            expect(decodeChatMessage(`&amp;#128558;&amp;#8205;&amp;#128168;`))
                .toBe('😮‍💨');
        });

        it('will correctly replace encoded emojis with the emoji', () => {
            expect(decodeChatMessage(`&amp;#01f62e&amp;#00200d&amp;#01f4a8`))
                .toBe('😮‍💨');
        });

        it('will correctly replace encoded characters and strip invalid tags', () => {
            expect(decodeChatMessage(`&lt;tag&gt;&#39;single&#39; &amp; &quot;quote&quot;&lt;/tag&gt;`))
                .toBe(`<tag>'single' & "quote"</tag>`);
        });

        it('will correctly allow appropriate html tags', () => {
            expect(decodeChatMessage(`&lt;a href=&quot;https://www.youtube.com&quot;&gt;test&lt;/a&gt;`))
                .toBe(`<a href="https://www.youtube.com">test</a>`);
        });

        it('will correctly strip javascript href attributes', () => {
            expect(decodeChatMessage(`&lt;a href=&quot;javascript:alert(&quot;yee&quot;)&quot;&gt;test&lt;/a&gt;`))
                .toBe(`<a href="alert("yee")">test</a>`);
        });


        it('will correctly strip onerror attributes', () => {
            expect(decodeChatMessage(`&lt;a onerror=&quot;alert(&quot;yee&quot;)&quot;&gt;test&lt;/a&gt;`))
                .toBe(`<a onerror="alert("yee")">test</a>`);
        });
    });
});